import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')

function file(relative) {
    return path.join(root, relative)
}

function read(relative) {
    return fs.readFileSync(file(relative), 'utf8')
}

function write(relative, value) {
    fs.writeFileSync(file(relative), value, 'utf8')
}

function replaceOnce(relative, needle, replacement) {
    const source = read(relative)
    const first = source.indexOf(needle)
    if (first < 0) throw new Error(`Missing patch anchor in ${relative}: ${needle.slice(0, 120)}`)
    if (source.indexOf(needle, first + needle.length) >= 0)
        throw new Error(`Ambiguous patch anchor in ${relative}: ${needle.slice(0, 120)}`)
    write(relative, source.slice(0, first) + replacement + source.slice(first + needle.length))
}

function insertBefore(relative, needle, addition) {
    replaceOnce(relative, needle, addition + needle)
}

