// Add explicit V4 contract tests without relying on network/model downloads.
write(
    'test/unit/recommendation-v4-integration.test.ts',
    `import fs from 'node:fs'\nimport path from 'node:path'\nimport os from 'node:os'\nimport { describe, expect, it } from 'vitest'\nimport { LibraryDatabase } from '../../src/library/database'\nimport { latestMigrationVersion } from '../../src/storage/sqlite/migrations'\nimport { VISUAL_MODEL_ID, VISUAL_MODEL_VERSION, VISUAL_SAMPLING_POLICY_VERSION } from '../../src/recommendation-v4/visual-style'\n\nconst root = path.resolve(import.meta.dirname, '../..')\nconst read = (file: string) => fs.readFileSync(path.join(root, file), 'utf8')\n\ndescribe('Recommendation V4 integration', () => {\n    it('adds only additive schema 10 visual storage', () => {\n        expect(latestMigrationVersion).toBe(10)\n        const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'pica-v4-'))\n        const database = new LibraryDatabase(path.join(dir, 'library.sqlite'))\n        const tables = (database as any).db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all().map((row: any) => row.name)\n        expect(tables).toContain('visual_embeddings')\n        database.close()\n        fs.rmSync(dir, { recursive: true, force: true })\n    })\n\n    it('records immediate sentiment independently from optional reasons', () => {\n        const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'pica-v4-feedback-'))\n        const database = new LibraryDatabase(path.join(dir, 'library.sqlite'))\n        database.importCatalog([{ comicId: 'comic-a', title: 'A', author: 'Author', tags: ['tag'], categories: [], finished: true }], 'test')\n        const feedback = database.recordUserEvent({ eventType: 'recommend_dislike', comicId: 'comic-a', source: 'test' })\n        expect(database.recommendationFeedback()[0]).toMatchObject({ comicId: 'comic-a', sentiment: 'dislike', reasons: [] })\n        database.recordUserEvent({ eventType: 'recommend_feedback_reason', comicId: 'comic-a', source: 'test', metadata: { parentFeedbackId: feedback.id, sentiment: 'dislike', reasons: ['style'] } })\n        expect(database.recommendationFeedback()[0].reasons).toEqual(['style'])\n        const changed = database.recordUserEvent({ eventType: 'recommend_like', comicId: 'comic-a', source: 'test' })\n        expect(database.recommendationFeedback()[0]).toMatchObject({ feedbackEventId: changed.id, sentiment: 'like', reasons: [] })\n        database.close()\n        fs.rmSync(dir, { recursive: true, force: true })\n    })\n\n    it('persists normalized versioned embeddings', () => {\n        const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'pica-v4-vector-'))\n        const database = new LibraryDatabase(path.join(dir, 'library.sqlite'))\n        database.importCatalog([{ comicId: 'comic-a', title: 'A', author: 'Author', tags: [], categories: [], finished: true }], 'test')\n        database.saveVisualEmbedding({ comicId: 'comic-a', modelId: VISUAL_MODEL_ID, modelVersion: VISUAL_MODEL_VERSION, samplingPolicyVersion: VISUAL_SAMPLING_POLICY_VERSION, embeddingKind: 'body', vector: [3,4], dimension: 2, sourceKind: 'LOCAL_PAGES', sampleCount: 6, confidence: 1, generatedAt: new Date(0).toISOString(), metadata: {} })\n        expect(database.listVisualEmbeddings()[0].vector).toEqual([0.6,0.8])\n        database.close()\n        fs.rmSync(dir, { recursive: true, force: true })\n    })\n\n    it('keeps reasons optional in UI and visual analysis lazy', () => {\n        const html = read('web/index.html')\n        const app = read('web/app.js')\n        const runtime = read('web/visual-runtime.js')\n        expect(html).toContain('id=\"recommend-feedback-reasons-toggle\"')\n        expect(app).toContain("eventType: sentiment === 'like' ? 'recommend_like' : 'recommend_dislike'")\n        expect(app.indexOf('state.recommendationFeedback[comicId] =')).toBeLessThan(app.indexOf("$('#recommend-feedback-dialog').showModal()"))\n        expect(runtime).toContain("onnx-community/dinov2-small")\n        expect(runtime).toContain('await import(VISUAL_RUNTIME.libraryUrl)')\n    })\n})\n`
)

// Beta architecture note for future audit/rebuilds.
write(
    'docs/RECOMMENDATION_V4_VISUAL_BETA.md',
    `# Recommendation V4 Visual + Feedback Beta\n\nThis branch is an unpublished beta. It layers explicit like/dislike feedback and local visual-style representations on top of the frozen Recommendation V3 recall/ranker.\n\n## Feedback contract\n\n- Like/dislike is committed immediately as an append-only event.\n- Optional reasons are a separate event and may be disabled entirely.\n- Latest sentiment wins for a comic.\n- A reason such as \`already_seen\`, \`topic\`, \`author\` or \`character\` does not become a strong negative visual-style signal. \`style\` does.\n\n## Visual contract\n\n- Encoder: DINOv2 Small through Transformers.js 4.2.0.\n- Page images remain local to Pica Library. The browser downloads model code/weights on first use; image content is not uploaded to the model host.\n- Sources: downloaded body pages (high confidence), bounded remote body-page sampling (medium/high confidence), or cover-only (low confidence).\n- Embeddings are versioned by model and sampling policy. Full comic pages are not retained by the visual index.\n- User style is multi-prototype, not one global centroid.\n- Missing visual data is neutral: candidates are not penalized.\n- Modes: OFF, SHADOW (audit only), LIVE (bounded low-weight reranking).\n- Visual vectors can also power Similar Style browsing.\n\n## Safety / release\n\nThis branch must not publish releases or tags. A test artifact is produced only after CI is green.\n`
)

